<script setup>
import { onBeforeUnmount, onMounted, reactive, ref } from 'vue';
const props = defineProps({ mode:String,indexUrl:String,createUrl:String,storeUrl:String,updateUrl:String,csrf:String,payload:String,errors:String,old:String });
const parse=(s,d={})=>{try{return s?JSON.parse(s):d}catch{return d}};
const details=parse(props.payload),issues=parse(props.errors),old=parse(props.old),order=details.order||{};
const form=reactive(Object.fromEntries(['user_id','book_id','book_price','quantity','payment_method','payment_status','order_status','full_name','phone','country','city','postal_code','address','note'].map(k=>[k,old[k]??order[k]??({quantity:1,payment_method:'cash_on_delivery',payment_status:'pending',order_status:'pending'}[k]??'')])));
const data=reactive({orders:[],stats:{},pagination:{},filters:{search:'',status:'',payment:'',date:''}});const loading=ref(true),error=ref('');let controller,timer;
async function load(url=location.href,push=false){controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const r=await fetch(url,{credentials:'same-origin',signal:controller.signal,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const d=await r.json();if(!r.ok)throw new Error(d.message||`Request failed (${r.status})`);data.orders=d.orders||[];data.stats=d.stats||{};data.pagination=d.pagination||{};data.filters={search:'',status:'',payment:'',date:'',...(d.filters||{})};if(push)history.pushState({},'',url)}catch(e){if(e.name!=='AbortError')error.value=e.message}finally{loading.value=false}}
function url(){const u=new URL(props.indexUrl,location.origin);for(const[k,v]of Object.entries(data.filters))if(v)u.searchParams.set(k,v);return u.href}function apply(){load(url(),true)}function search(){clearTimeout(timer);timer=setTimeout(apply,350)}function page(l){if(l.url)load(l.url,true)}function pop(){load(location.href)}
async function destroy(o){let ok=true;if(window.Swal){const x=await window.Swal.fire({title:'Delete order?',text:`Order ${o.number} can only be deleted if it has no refunds, is unpaid and undelivered.`,icon:'warning',showCancelButton:true,confirmButtonText:'Delete'});ok=x.isConfirmed}else ok=confirm(`Delete order ${o.number}?`);if(!ok)return;try{const r=await fetch(o.delete_url,{method:'DELETE',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf,'X-Requested-With':'XMLHttpRequest'}});const d=await r.json();if(!r.ok)throw new Error(d.message||'Unable to delete order.');await load(location.href)}catch(e){error.value=e.message}}
onMounted(()=>{const p=new URLSearchParams(location.search);data.filters={search:p.get('search')||'',status:p.get('status')||'',payment:p.get('payment')||'',date:p.get('date')||''};if(props.mode==='index')load(props.indexUrl+location.search);window.addEventListener('popstate',pop)});onBeforeUnmount(()=>{clearTimeout(timer);controller?.abort();window.removeEventListener('popstate',pop)});
</script>

<template>
<template v-if="mode==='index'">
 <section class="orders-hero"><div class="orders-hero-content"><span class="orders-hero-badge"><i class="bi bi-bag-check"></i> Marketplace Operations</span><h1>Every order, under control.</h1><p>Manage customer orders, payments and delivery progress from one organised workspace.</p></div><div class="orders-hero-mark"><i class="bi bi-cart3"></i></div></section>
 <section class="orders-stats"><div class="order-stat-card stat-blue"><div class="order-stat-content"><span>Total Orders</span><strong>{{ data.stats.total??'—' }}</strong></div><div class="order-stat-icon"><i class="bi bi-cart-check"></i></div></div><div class="order-stat-card stat-orange"><div class="order-stat-content"><span>Pending</span><strong>{{ data.stats.pending??'—' }}</strong></div><div class="order-stat-icon"><i class="bi bi-hourglass-split"></i></div></div><div class="order-stat-card stat-green"><div class="order-stat-content"><span>Delivered</span><strong>{{ data.stats.delivered??'—' }}</strong></div><div class="order-stat-icon"><i class="bi bi-check-circle"></i></div></div><div class="order-stat-card stat-purple"><div class="order-stat-content"><span>Revenue</span><strong>${{ Number(data.stats.revenue||0).toFixed(2) }}</strong></div><div class="order-stat-icon"><i class="bi bi-currency-dollar"></i></div></div></section>
 <section class="dashboard-panel orders-panel"><div class="orders-panel-header"><div class="orders-heading-content"><span class="eyebrow">Order directory</span><h5>All Orders</h5><p>Search, filter and review every marketplace order.</p></div><div class="orders-header-action"><a :href="createUrl" class="orders-add-btn"><i class="bi bi-plus-lg"></i><span>Add Order</span></a></div></div>
  <form class="order-filters" @submit.prevent="apply"><div class="order-filter-group order-filter-search"><label for="order-search">Search</label><input id="order-search" v-model="data.filters.search" class="order-filter-select" placeholder="Order, customer, phone, book..." @input="search"></div><div class="order-filter-group"><label for="order-status">Order Status</label><select id="order-status" v-model="data.filters.status" class="order-filter-select"><option value="">All Status</option><option v-for="s in ['pending','processing','shipped','delivered','cancelled']" :key="s">{{ s }}</option></select></div><div class="order-filter-group"><label for="order-payment">Payment Status</label><select id="order-payment" v-model="data.filters.payment" class="order-filter-select"><option value="">All Payments</option><option v-for="s in ['pending','paid','failed','refunded']" :key="s">{{ s }}</option></select></div><div class="order-filter-group"><label for="order-date">Date</label><input id="order-date" v-model="data.filters.date" type="date" class="order-filter-select"></div><div class="order-filter-actions"><button class="order-filter-btn"><i class="bi bi-funnel"></i> Filter</button><button v-if="Object.values(data.filters).some(Boolean)" type="button" class="order-reset-btn" @click="data.filters={search:'',status:'',payment:'',date:''};apply()">Clear</button></div></form>
  <div v-if="error" class="alert alert-danger">{{ error }} <button class="btn btn-light btn-sm" @click="load()">Retry</button></div><div class="orders-table-wrap"><table class="orders-table"><thead><tr><th class="orders-col-id">#</th><th class="orders-col-customer">Customer</th><th class="orders-col-book">Book</th><th class="orders-col-total">Total</th><th class="orders-col-payment">Payment</th><th class="orders-col-status">Status</th><th class="orders-col-date">Date</th><th class="orders-col-actions">Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="8" class="text-center py-4">Loading orders…</td></tr><tr v-for="o in data.orders" v-else :key="o.id"><td><strong>{{ o.number }}</strong></td><td><strong>{{ o.customer||'—' }}</strong><small class="d-block">{{ o.email }}</small></td><td>{{ o.book||'—' }}<small class="d-block">Qty {{ o.quantity }}</small></td><td>${{ o.total }}</td><td><span class="order-status-pill" :class="`payment-${o.payment_status}`"><i class="bi bi-circle-fill"></i>{{ o.payment_status }}</span></td><td><span class="order-status-pill" :class="`order-status-${o.order_status}`"><i class="bi bi-circle-fill"></i>{{ o.order_status }}</span></td><td>{{ o.date }}</td><td><div class="orders-actions"><a :href="o.show_url" class="order-action-btn" title="View"><i class="bi bi-eye"></i></a><a :href="o.edit_url" class="order-action-btn" title="Edit"><i class="bi bi-pencil"></i></a><button class="order-action-btn" title="Delete" @click="destroy(o)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="!loading&&!data.orders.length"><td colspan="8"><div class="orders-empty-state"><i class="bi bi-bag"></i><strong>No orders found</strong><span>Try changing your filters.</span></div></td></tr></tbody></table></div><div v-if="data.pagination.total>10" class="orders-pagination"><span>Showing {{ data.pagination.first_item }} to {{ data.pagination.last_item }} of {{ data.pagination.total }} orders</span><nav class="orders-pagination-pages"><button v-for="(l,i) in data.pagination.links" :key="i" class="orders-pager-btn" :class="{active:l.active,disabled:!l.url}" :disabled="!l.url" @click="page(l)" v-html="l.label.replace('&laquo;','‹').replace('&raquo;','›')"></button></nav></div>
 </section>
</template>
<template v-else-if="mode==='create'||mode==='edit'">
 <div class="orders-edit-page"><div class="orders-edit-header"><div><span class="orders-edit-eyebrow"><i class="bi bi-receipt"></i> Order Management</span><h1>{{ mode==='edit'?'Edit Order':'Create Order' }}</h1><p>Manage customer, order, payment and delivery information.</p></div><a :href="indexUrl" class="orders-edit-back"><i class="bi bi-arrow-left"></i> Back to Orders</a></div><div v-if="Object.keys(issues).length" class="alert alert-danger"><ul class="mb-0"><li v-for="(v,k) in issues" :key="k">{{ v[0] }}</li></ul></div><form :action="mode==='edit'?updateUrl:storeUrl" method="POST" class="orders-edit-form"><input type="hidden" name="_token" :value="csrf"><input v-if="mode==='edit'" type="hidden" name="_method" value="PUT"><div class="orders-edit-card"><div class="orders-edit-card-header"><div class="orders-edit-card-icon"><i class="bi bi-cart-check"></i></div><div class="orders-edit-card-title"><strong>Order and customer information</strong><span>Customer, book, pricing and payment details.</span></div></div><div class="orders-edit-grid">
 <div class="orders-edit-field"><label class="orders-edit-label">Customer</label><select v-model="form.user_id" name="user_id" class="orders-edit-select" required><option value="">Select customer</option><option v-for="u in details.users||[]" :key="u.id" :value="u.id">{{ u.name||[u.first_name,u.last_name].filter(Boolean).join(' ') }} — {{ u.email }}</option></select></div><div class="orders-edit-field"><label class="orders-edit-label">Book</label><select v-model="form.book_id" name="book_id" class="orders-edit-select" required><option value="">Select book</option><option v-for="b in details.books||[]" :key="b.id" :value="b.id">{{ b.title }}</option></select></div><div class="orders-edit-field"><label class="orders-edit-label">Full name</label><input v-model="form.full_name" name="full_name" class="orders-edit-input" required></div><div class="orders-edit-field"><label class="orders-edit-label">Phone</label><input v-model="form.phone" name="phone" class="orders-edit-input" required></div><div class="orders-edit-field"><label class="orders-edit-label">Quantity</label><input v-model="form.quantity" name="quantity" type="number" min="1" class="orders-edit-input" required></div><div class="orders-edit-field"><label class="orders-edit-label">Book price</label><input v-model="form.book_price" name="book_price" type="number" min="0" step="0.01" class="orders-edit-input" required></div><div class="orders-edit-field"><label class="orders-edit-label">Payment method</label><select v-model="form.payment_method" name="payment_method" class="orders-edit-select" required><option value="cash_on_delivery">Cash On Delivery</option><option value="credit_card">Credit Card</option><option value="debit_card">Debit Card</option><option value="paypal">PayPal</option></select></div><div class="orders-edit-field"><label class="orders-edit-label">Payment status</label><select v-model="form.payment_status" name="payment_status" class="orders-edit-select" required><option v-for="s in ['pending','paid','failed','refunded']" :key="s">{{ s }}</option></select></div><div class="orders-edit-field"><label class="orders-edit-label">Order status</label><select v-model="form.order_status" name="order_status" class="orders-edit-select" required><option v-for="s in ['pending','processing','shipped','delivered','cancelled']" :key="s">{{ s }}</option></select></div><div class="orders-edit-field"><label class="orders-edit-label">Country</label><input v-model="form.country" name="country" class="orders-edit-input" required></div><div class="orders-edit-field"><label class="orders-edit-label">City</label><input v-model="form.city" name="city" class="orders-edit-input" required></div><div class="orders-edit-field"><label class="orders-edit-label">Postal code</label><input v-model="form.postal_code" name="postal_code" class="orders-edit-input"></div><div class="orders-edit-field span-6"><label class="orders-edit-label">Address</label><textarea v-model="form.address" name="address" class="orders-edit-input" required></textarea></div><div class="orders-edit-field span-6"><label class="orders-edit-label">Note</label><textarea v-model="form.note" name="note" class="orders-edit-input"></textarea></div></div></div><div class="orders-edit-actions"><a :href="indexUrl" class="orders-edit-back">Cancel</a><button type="submit" class="orders-edit-submit"><i class="bi bi-check-circle"></i> {{ mode==='edit'?'Update Order':'Create Order' }}</button></div></form></div>
</template>
<template v-else-if="mode==='show'"><div class="orders-show-page"><div class="orders-show-header"><div><span class="orders-edit-eyebrow"><i class="bi bi-receipt"></i> Order Management</span><h1>Order Details</h1><p>View complete order information.</p></div><div class="orders-show-header-actions"><a :href="indexUrl" class="orders-edit-back"><i class="bi bi-arrow-left"></i> Back to Orders</a><a :href="details.edit_url" class="orders-edit-submit"><i class="bi bi-pencil"></i> Edit Order</a></div></div><div class="orders-show-summary"><div class="orders-show-summary-item"><span>Order Number</span><strong>{{ order.order_number||`#${order.id}` }}</strong></div><div class="orders-show-summary-item"><span>Total</span><strong>${{ Number(order.total_price).toFixed(2) }}</strong></div><div class="orders-show-summary-item"><span>Payment</span><em class="order-status-pill" :class="`payment-${order.payment_status}`">{{ order.payment_status }}</em></div><div class="orders-show-summary-item"><span>Status</span><em class="order-status-pill" :class="`order-status-${order.order_status}`">{{ order.order_status }}</em></div></div><div class="orders-show-grid"><div class="orders-edit-card"><div class="orders-edit-card-header"><div class="orders-edit-card-icon"><i class="bi bi-cart-check"></i></div><div class="orders-edit-card-title"><strong>Order Information</strong><span>Quantity, pricing and dates</span></div></div><div class="orders-show-body"><div class="orders-show-row"><span>Order Number</span><strong>{{ order.order_number }}</strong></div><div class="orders-show-row"><span>Quantity</span><strong>{{ order.quantity }}</strong></div><div class="orders-show-row"><span>Book Price</span><strong>${{ Number(order.book_price).toFixed(2) }}</strong></div><div class="orders-show-row"><span>Total Price</span><strong>${{ Number(order.total_price).toFixed(2) }}</strong></div><div class="orders-show-row"><span>Book</span><strong>{{ details.book?.title||'—' }}</strong></div><div class="orders-show-row"><span>Customer</span><strong>{{ details.user?.name||order.full_name }}<small>{{ details.user?.email }}</small></strong></div></div></div><div class="orders-edit-card"><div class="orders-edit-card-header"><div class="orders-edit-card-icon"><i class="bi bi-truck"></i></div><div class="orders-edit-card-title"><strong>Delivery Information</strong><span>Shipping address and contact details</span></div></div><div class="orders-show-body"><div class="orders-show-row"><span>Name</span><strong>{{ order.full_name }}</strong></div><div class="orders-show-row"><span>Phone</span><strong>{{ order.phone }}</strong></div><div class="orders-show-row"><span>Address</span><strong>{{ order.address }}, {{ order.city }}, {{ order.country }} {{ order.postal_code }}</strong></div><div class="orders-show-row"><span>Payment Method</span><strong>{{ order.payment_method }}</strong></div><div class="orders-show-row"><span>Note</span><strong>{{ order.note||'—' }}</strong></div></div></div></div></div></template>
</template>
